import {DUAL_GUIDE_TEXT} from './guide-dual-text.js';
import {PHYSIOLOGY_DEFAULTS as R,BODY_GENE_DEFAULTS as G,PHYSIOLOGY_FIELDS,BODY_GENE_FIELDS} from './physiology-settings.js';
import {bodyPlan,createBody,bodyCapacities,basalRate,bodySpeed,remainsMass,pregnancyPlan} from './body-physiology.js';
import {createDigestion,ingestFood,advanceDigestion} from './digestion.js';
import {foodEnergies} from './physiology-settings.js';
import {NUMERIC_MUTATION_RULES as N} from './numeric-mutation.js';
import {SUBSTEPS,DT} from './action-timing.js';
import {CELL_INPUTS,CONTEXT_INPUTS,CANDIDATE_INPUTS,ATTENTION_INPUTS,OPERATION_NAMES} from './physiology-brain-layout.js';
import {p,v,a,table,details} from './guide-markup.js';
const plan=bodyPlan(G),body=createBody(plan,R),cap=bodyCapacities(body,R),preg=pregnancyPlan(plan,R);
const param=(group,key)=>`<span class="guide-value" data-guide-param="${group}.${key}"></span>`;
export function digestionGuideExample(type=0,amount=R.inventoryCapacity){
 const d=createDigestion(plan.retentionSteps,0),q=foodEnergies(R);ingestFood(d,type,amount,cap.volume,q);let energy=0;
 for(let tick=1;tick<=plan.retentionSteps;tick++)energy+=advanceDigestion(d,tick,cap.volume,[G.Fg,G.Ff,G.Fm],q);
 return energy;
}
const bodyTable=table('Эталонный основатель — значения по умолчанию',['Величина','Значение'],[
 ['Масса тканей',v(body.L)],['Энергия / ёмкость',`${v(body.energy)} / ${v(cap.energy)}`],['Здоровье',v(cap.health)],['Желудок',v(cap.volume,'порции')],['Скорость',v(bodySpeed(body,R),'клетки/Т')],['Содержание тела и пищеварения',v(basalRate(body,plan,R),'энергии/Т')]]);
const links=p(`Дальше: ${a('food','питание')}, ${a('selection','развитие ребёнка')}, ${a('actions','действия и атаки')}, ${a('structure-evolution','мутации')}.`);
export const PHYSIOLOGY_GUIDE_TEXT={
 'guide-brain-cost-body':DUAL_GUIDE_TEXT['guide-brain-cost-body']
 .replace('Смертельная оплата не начинает выбранное действие; дефицит оплачивается здоровьем по обычной физике.','Уже выполненные вычисления входят в обязательные расходы следующего интервала вместе с содержанием тела. Сначала их оплачивают энергия и разрешённый катаболизм; остаточный дефицит повреждает здоровье. Добровольная двигательная работа не запускает катаболизм.')
 .replace('Покой также оплачивает физическую ставку прежнего ожидания.','В покое двигательных расходов нет; содержание тела, пищеварение и фактические проверки мозга продолжаются.'),

 'guide-energy-body':p('Тело хранит ткани, энергию и здоровье. Чем больше тканей, тем больше запас энергии и максимум здоровья. При голоде часть тканей может оплатить обязательные расходы; это уменьшает тело и его возможности. Рекордная масса сохраняет размер органов, поэтому похудевший житель не теряет желудок сразу.')
 +bodyTable+p(`Пример: исходный основатель имеет массу ${v(body.L)}, а его неприкосновенная органная часть — ${v(body.M*R.organFraction)}. Запас энергии не равен всей энергии тканей: это отдельные величины.`)
 +details('Точные правила бюджета',p('За подшаг сначала усваивается пища. Затем оплачиваются содержание тела и уже выполненные вычисления. При нехватке энергии расщепляются доступные ткани с потерями; непокрытый остаток повреждает здоровье. Если здоровье исчерпано, житель погибает до лечения.')
 +p('После обязательных расходов энергия по очереди идёт на мотор текущего действия, вынашивание, рост и лечение. Эти добровольные расходы не запускают катаболизм. Если мотор не оплачен, действие прерывается. Избыток усвоенного сверх ёмкости ещё можно потратить в этом подшаге; окончательный избыток теряется в конце.')
 +p('L — текущие ткани, M — наибольшая достигнутая масса. Органы O = organFraction × M; O ≤ L ≤ M. Emax = energyPerMass × L; Hmax = healthPerMass × L; V = volumePerOrgan × O. Катаболизм сохраняет относительное здоровье. Рост добавляет здоровую ткань и сохраняет абсолютную рану. После окна развития восстанавливается только ранее достигнутая масса.')
 +p(`Рост требует запаса выше ${param('physiology','growthThreshold')}; лечение сохраняет долю энергии ${param('physiology','healingReserve')}. Отдельной смерти по возрасту в новой модели нет.`))+links,
 'guide-food-path':p('Пища проходит через землю, инвентарь и желудок. Житель отдельно выбирает траву, плоды или мясо. Одна и та же порция даёт разную энергию в зависимости от вида пищи, мощности пищеварения и срока её удержания.')
 +table('Пример: полный желудок эталонного основателя, один вид пищи',['Пища','Энергия усвоена за полный срок'],['Трава','Плоды','Мясо'].map((name,j)=>[name,v(digestionGuideExample(j))]))
 +p('Это расчёт общими функциями пищеварения при настройках по умолчанию, без нового приёма пищи. Даже после извлечения всей энергии объём остаётся занятым до выведения.')
 +p('Например, из запаса <code>3 порции</code> при свободном месте <code>0,7 порции</code> житель съест <code>0,7</code>, а <code>2,3</code> останется в инвентаре. Пример показывает дробный перенос; размеры запасов определяются выбранными настройками.')
 +details('Порция, ёмкость и пищевые группы',p(`Общий инвентарь в выбранном контексте: ${param('physiology','inventoryCapacity')}. Сбор и выкладывание переносят не больше ${param('physiology','portionPerAction')} за действие. При еде житель проглатывает столько выбранного вида пищи, сколько есть в запасе и помещается в желудок. Остаток сохраняется в запасе. Полный желудок ничего не списывает. Время одного приёма — ${param('physiology','eatSteps')} независимо от количества.`)
 +p('Пища объединяется в ограниченное кольцо возрастных групп. Срок считается от начала группы, поэтому поздний приём в ту же группу удерживается немного меньше. На последнем подшаге сначала идёт усвоение, затем выведение; новый приём пищи происходит позже и начинает усваиваться со следующего подшага.')
 +p('Для каждого вида предел за подшаг равен F × V × Q. Он распределяется между возрастными группами пропорционально остаткам энергии этого вида. У трёх видов независимые мощности, дополнительного общего потолка нет. Все доли берутся из одного снимка. Мощность F уже задана на подшаг: повторно умножать её на длительность подшага нельзя.'))+links,
 'guide-food-sources':p('На суше восстанавливается трава. Плоды появляются в прежних источниках по их календарю. Мясо появляется из останков и быстро портится вне желудка.')
 +table('Где искать пищу',['Вид','Источник'],[['Трава','Сухая клетка с восстанавливаемым запасом'],['Плоды','Островок или куст с календарём восстановления'],['Мясо','Останки тела и оплаченной части плода']])
 +p(`При старте максимум травы каждой сухой клетки выбирается из непрерывного диапазона ${v(R.grassMin)}–${v(R.grassMax)} порций, и клетка заполнена. Восстановление в выбранном контексте — ${param('physiology','grassRegrowth')}. Трава отмечена светлыми штрихами, плоды — ягодами, мясо — красноватым прямоугольником.`)
 +details('Обновление ресурсов',p(`Восстановление травы рассчитывается по прошедшему времени, чтение карты не меняет RNG. Каждая целая порция мяса имеет вероятность сохраниться согласно полураспаду ${param('physiology','meatHalfLife')}; дробный остаток сохраняется либо пропадает целиком. Это действует и на переносимое мясо. Перекладывание не начинает срок заново. В желудке порча заменяется обычным пищеварением.`))+links,
 'guide-food-deposits':p('Выложенная еда сохраняет свой вид. При гибели жителя инвентарь выпадает отдельно от тканей; энергия и содержимое желудка не превращаются в дополнительные порции.')
 +p(`Пример при базовых настройках: тело основателя даёт ${v(remainsMass(body,R),'порций мяса')}. Если погибший вынашивал полностью оплаченный плод плановой массы ${v(plan.birthMass)}, его останки добавляются отдельно.`)
 +details('Останки и место на земле',p('Масса останков равна L минус невосстанавливаемая доля органов. Масса плода определяется уже оплаченной долей. Одна смерть создаёт останки один раз. Ограничение растительных запасов клетки не обрезает мясо; прежние порции на клетке сохраняются.'))+links,
 'guide-birth-body':p('Размножение разделено на зачатие, вынашивание и роды. При зачатии один раз создаётся геном ребёнка. Родитель затем оплачивает развитие небольшими платежами; недоплата уменьшает ребёнка, но не переносит дату родов.')
 +table('Состояния размножения',['Этап','Что происходит'],[['Зачатие','Выбор мозга и создание наследуемого генома ребёнка'],['Вынашивание','Обычная жизнь с малыми платежами'],['Роды','Непрерываемый период; после него исход по оплаченной доле']])
 +p(`Пример по умолчанию: плановая масса новорождённого ${v(plan.birthMass)}, полная стоимость подготовки ${v(preg.cost)} энергии. Вынашивание занимает ${v(plan.pregnancySteps/SUBSTEPS,'Т')}, после него идут ${v(R.birthSteps/SUBSTEPS,'Т')} родов. Половина оплаты даёт половину плановой массы и соответствующие ей ёмкости.`)
 +details('Допуск, платежи и исход',p('Зачатие доступно после наследуемого возраста допуска, если беременности ещё нет и численность ниже лимита. Отдельного порога энергии или здоровья, цены начала и паузы после родов нет. Лимит запрещает новые зачатия, но уже начатые беременности завершаются: живых временно может стать больше лимита.')
 +p('Срок вынашивания фиксируется по родителю при зачатии; план массы — по уже мутировавшим генам ребёнка. Каждый подшаг платится не более обычной доли и доступной энергии. Пропущенные платежи не наверстываются. После последнего платежа начинается непрерываемый период родов: прежнее действие отменяется, содержание тела, пищеварение и уязвимость сохраняются.')
 +p('При нулевой оплате живой ребёнок не появляется. При положительной доле он рождается здоровым, с предусмотренным запасом энергии и пустым желудком, инвентарём, памятью и личными поправками. Первый активный подшаг идёт после рождения. Гибель родителя до исхода отменяет рождение и оставляет мясо оплаченной части плода.'))+links,
 'guide-actions-body':p('Основной мозг выбирает направление движения, вид собираемой или съедаемой пищи, покой, зачатие, выкладывание либо конкретную жертву. Эффект отложенного действия появляется при завершении, если условия ещё позволяют его выполнить.')
 +table('Длительности при настройках по умолчанию',['Процесс','Время'],[['Сбор',v(R.gatherSteps/SUBSTEPS,'Т')],['Еда',v(R.eatSteps/SUBSTEPS,'Т')],['Выкладывание',v(R.depositSteps/SUBSTEPS,'Т')],['Замах',v(R.attackSteps/SUBSTEPS,'Т')],['Роды',v(R.birthSteps/SUBSTEPS,'Т')]])
 +p('Например, если жертва завершает выход с клетки в тот же подшаг, что и замах, движение разрешается раньше удара, и атака не попадает. Два смертельных удара на одной клетке могут убить обоих: ущерб каждого рассчитывается до применения этих ударов.')
 +details('Движение, продолжение и атака',p('Скорость зависит от рекордного размера и отношения текущей массы к рекордной. Длительность перехода округляется вверх до подшага и фиксируется при старте. Продолжение сохраняет прогресс только для того же действия, вида пищи и цели. Отмена теряет уже уплаченную энергию; рисунок возвращается на исходную клетку.')
 +p('Атаковать можно другого живого жителя своей клетки. Стоимость замаха фиксируется при старте по физической цене перехода; ущерб при попадании зависит от текущей массы и относительного здоровья атакующего. Смерть, уход или смена цели не превращаются в попадание по другому соседу. Мозг не получает отдельной награды за убийство.'))+links,
 'guide-time-body':p(`Одна Т разделена на ${v(SUBSTEPS)} подшагов по ${v(DT,'Т')}. Все жители проходят одинаковый порядок фаз независимо от числа вычислителей. Случайность физических событий принадлежит координатору мира.`)
 +p('Пример: роды и смертельный удар могут завершаться на одной границе. Удары разрешаются раньше рождения, поэтому погибший родитель не рожает после смерти.')
 +details('Общая последовательность', '<ol><li>Общий снимок наблюдений, память, проверка внимания, оценка и подтверждение выбора.</li><li>Ресурсы и пищеварение; обязательный бюджет и гибель от истощения.</li><li>Оплата мотора, платежи беременности, рост и лечение.</li><li>Все завершённые перемещения; затем все удары и гибель от них.</li><li>Остальные завершения в общей случайной очереди, исход родов и начало следующего периода родов.</li><li>Запись состояния; новорождённый действует со следующего подшага.</li></ol>')+links,
 'guide-genome-body':p('Геном v18 содержит наследуемые веса основного мозга и диспетчера, их изменяемые структуры, поведенческие свойства, гены тела и пищеварения. Личная память и выученные поправки в него не входят.')
 +p('Пример: у ребёнка может увеличиться срок удержания пищи без изменения мощности усвоения. Тогда пища занимает место дольше и успевает отдать больше энергии; это также меняет частоту полезных приёмов пищи.')
 +details('Гены тела',table('Начальные значения в выбранном контексте',['Ген','Значение'],Object.entries(BODY_GENE_FIELDS).map(([key,f])=>[f.label,param('bodyGenes',key)]))+p('Сроки остаются вещественными генами; для исполнения они один раз округляются вверх до целого подшага. Масса не является независимым геном: план развития выводится из строительной мощности, окна роста и доли рождения.'))+links,
 'guide-structure-evolution-body':p('Численные изменения и перестройка сети имеют независимые регуляторы. В каждой включённой численной группе все унаследованные параметры меняются один раз; структуры сохраняют отдельные вероятность события и силу.')
 +p(`Для нулевого веса масштаб ${v(N.weightScale)} задаёт ненулевой нижний шаг ${v(N.minimumFraction*N.weightScale)}. Поэтому нулевая исходящая связь нового нейрона может измениться при следующей передаче генома. Новые параметры не проходят числовую мутацию повторно в том же зачатии.`)
 +details('Распределение и наследование регуляторов',p('В семи численных группах A задаёт форму распределения величины шага, r — относительный потолок. Это не вероятность пропустить ген. Знак случаен; допустимые границы отражают шаг, а не обрезают его. Семь пар относятся к поведению, весам диспетчера, весам контекста, кодировщику, проекциям цели/операции и прямой оценке.')
 +p(`По умолчанию A = ${v(N.shape)}, r = ${v(N.ceiling)}. Потолок r лежит от ${v(N.ceilingMin)} до ${v(N.ceilingMax)}, A положителен. Гены тела входят в поведенческую группу, но используют собственные базовые масштабы.`)
 +p('Параметры мутируют по родительским регуляторам на начало зачатия. Затем все включённые регуляторы меняются один раз по родительскому поведенческому профилю, даже если сами поведенческие свойства отключены. Выключенная группа сохраняет и параметры, и свою пару регуляторов. Общий запрет мутаций сохраняет весь геном.')
 +p('После численной части выполняются независимые структурные события по родительским p/s. Сохраняются прямые связи вперёд, пропуски слоёв и возможность нуля скрытых нейронов; циклов нет. Новому нейрону дают ненулевой вход и нулевой выход.'))+links,
 'guide-physiology-parameters':table('Физические правила выбранного мира или варианта',['Параметр','Значение'],Object.entries(PHYSIOLOGY_FIELDS).map(([key,f])=>[f.label,param('physiology',key)])),
 'wiki-saves':p('«Сохранить мир» записывает полное состояние: тела, пищевые группы, беременность и геном плода, процессы, ресурсы, случайные генераторы, память и личное обучение. «Загрузить мир» проверяет файл целиком перед заменой текущего мира.')
 +table('Совместимость новой физики',['Файл','Правило'],[['Мир v5','Точное продолжение новой модели'],['Прежний полный мир','Не запускается под новой физикой; используйте соответствующий прежний выпуск'],['Геном v18','Основа нового мира; без личной памяти'],['Прежние геномы и отчёты','Продолжают читаться для анализа'],['План v4','Настройки нового опыта; старый p/s не превращается в A/r']])
 +p('Например, сохранение посреди вынашивания продолжает тот же график платежей с тем же геномом плода. Геном отдельно этого состояния не содержит.')
 +details('Ошибка загрузки',p('Повреждённые размеры сети, тело, пищевые группы, календарь или несовместимая схема отклоняются. Уже открытый мир остаётся на месте. Отсутствовавшее в старом отчёте значение показывается как отсутствие данных, а не ноль.')),
 'guide-observation-body':p('Житель видит своё тело и локальные клетки. На видимых клетках различаются трава, плоды и мясо, а у соседей — размер, относительное здоровье и текущее действие. Наблюдатель видит карту целиком, но мозг этих сведений не получает.')
 +p('Например, житель замечает замах в свою сторону и может выбрать уход. Энергию жертвы, её геном и ещё не принятое решение он не знает.')
 +details('Снимок и память',p('Координатор готовит одинаковый по времени снимок до подтверждения новых выборов. Числовые признаки не содержат глобальных координат и ID. Непрозрачный ключ жертвы нужен только для исполнения выбранной атаки. Память отдельно накапливает наблюдения трёх видов пищи; скрытая клетка не обновляется сама.')), 
 'guide-feelings-body':p('Самочувствие складывается из наследуемых чувствительностей к относительной энергии, относительному здоровью и заполненности желудка. Положительный коэффициент делает увеличение величины приятным; отрицательный меняет знак предпочтения.')
 +p('Например, два тела разного размера с одинаковыми долями энергии и здоровья имеют одинаковые входы ощущений при одинаковом геноме предпочтений. Размер не даёт бесплатного субъективного преимущества через абсолютные числа.')
 +details('Проценты и обучение',p('Проценты во вкладке «Предпочтения» — подписанные коэффициенты, нормированные на сумму их модулей. Это не вероятность действий. Изменение самочувствия накапливается во временном переходе и используется для обучения основного мозга. Отдельной назначенной награды за еду, убийство или рождение нет.')),
 'guide-brain-structure-body':p('Кодировщик одинаково обрабатывает клетки. Контекст ситуации объединяет состояние тела, окружение, память и текущий процесс. Проекции цели и операции сопоставляют эту ситуацию с каждым допустимым вариантом; прямая оценка добавляет линейную часть результата.')
 +table('Входы схемы v18',['Блок','Размер входа'],[['Клетка',v(CELL_INPUTS)],['Контекст',v(CONTEXT_INPUTS)],['Вариант',v(CANDIDATE_INPUTS)],['Диспетчер',v(ATTENTION_INPUTS)],['Виды операций',v(OPERATION_NAMES.length)]])
 +p('Например, сбор травы и сбор плодов на одной клетке используют общий контекст, но разные признаки вида пищи. Атаки двух соседей используют разные признаки наблюдаемой жертвы.')
 +details('Что эволюционирует',p('Скрытые нейроны и связи изменяются только в контексте и диспетчере. Кодировщик, линейные проекции и прямая оценка сохраняют устройство, но их веса наследуются с отдельными числовыми регуляторами. Основной мозг обучает личные поправки; диспетчер имеет только наследуемые веса. Числа «цель 1», «цель 2» на схеме обозначают координаты выученного представления, а не назначенные жизненные цели.')),
};
